dark_red3 = "#442022"
dark_red4 = "#704144"

green0    = "#8ea84d"
green1    = "#6db269"

orange0   = "#ff7550"
orange1   = "#eb842b"

pink0     = "#622b30"
pink1     = "#d2505f"
pink2     = "#d95362"
pink3     = "#c79295"
pink4     = "#e97e8a"

violet0   = "#ce8b9f"

white0    = "#cebabf"
